/bin/bash -lc "apply_patch <<'PATCH'
*** Begin Patch
*** Update File: supabase/config.toml
@@
 [edge_runtime]
 enabled = true
 policy = \"per_worker\"
 inspector_port = 8083
 deno_version = 2
+
+[functions.user-stats]
+verify_jwt = false

 [analytics]
 enabled = true
*** Add File: supabase/functions/user-stats/index.ts
+import { withSupabase } from \"npm:@supabase/server\";
+
+const UUID_PATTERN = /"'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
+
+export default {
+  fetch: withSupabase({ auth: ["user", "secret"] }, async (request, ctx) => {
+    if (request.method !== "POST") {
+      return Response.json({ error: "Method not allowed" }, { status: 405, headers: { Allow: "POST" } });
+    }
+
+    let userId: string;
+    let supabase;
+
+    if (ctx.authMode === "user") {
+      userId = ctx.userClaims.id;
+      supabase = ctx.supabase;
+    } else if (ctx.authMode === "secret") {
+      let body: unknown;
+      try {
+        body = await request.json();
+      } catch {
+        return Response.json({ error: "Request body must be valid JSON" }, { status: 400 });
+      }
+
+      if (typeof body !== "object" || body === null || Array.isArray(body)) {
+        return Response.json({ error: "Request body must be a JSON object" }, { status: 400 });
+      }
+
+      const requestedUserId = (body as { user_id?: unknown }).user_id;
+      if (typeof requestedUserId !== "string" || !UUID_PATTERN.test(requestedUserId)) {
+        return Response.json({ error: "A valid user_id is required" }, { status: 400 });
+      }
+
+      userId = requestedUserId;
+      supabase = ctx.supabaseAdmin;
+    } else {
+      return Response.json({ error: "Unauthorized" }, { status: 401 });
+    }
+
+    const { data, error } = await supabase
+      .from("user_stats")
+      .select("*")
+      .eq("user_id", userId);
+
+    if (error) {
+      return Response.json({ error: "Failed to fetch user stats" }, { status: 500 });
+    }
+
+    return Response.json(data);
+  }),
+};
*** End Patch
PATCH
printf '"'\\n--- matching changelog notes ---\\n'
